def blog_paragraphs(title,topic,fields,owner,section_index):
 head=BLOG_HEADS[section_index]
 return [
  f'{head} for {title} begins with a bounded operating question about {topic}. The record captures {fields}. Label every value as observed, client-stated, internally interpreted, owner-approved, executed, contradicted, expired, or still unavailable. Control OAM-1013-{section_index+1:02d} stores the source location, effective time, responsible actor, allowed next step, stop condition, and review receipt. That structure lets another authorized reviewer reconstruct why the item advanced or paused without relying on inbox memory or an informal promise.',
  f'At the {head.lower()} checkpoint for {title}, the outsourced account-management specialist may collect records, normalize identifiers, compare versions, prepare a decision packet, schedule an approved follow-up, and report verified state. The {owner} retains consequential judgment and approval. Commercial terms, legal conclusions, privacy determinations, security exceptions, refunds, credits, contract changes, access administration, and public claims never transfer merely because the specialist prepared the evidence. If identity, scope, authority, or destination is uncertain, stop the dependent action, preserve the safe interim state, name the decision owner, and give the client only a verified next-update time.',
  f'Rehearse the {head.lower()} step of {title} with an ordinary case and with a missing source, wrong account, stale instruction, conflicting version, inaccessible system, unavailable owner, rejected destination, late client correction, and apparent completion that lacks downstream proof. Use synthetic personal and commercial data during testing. A pass requires the approved result to match the correct client, record, period, and system; temporary access must expire; duplicate work must be linked; the client-facing message must match the decision; and a reviewer must be able to reproduce closure from retained evidence. Record residual questions instead of forcing a green status.'
 ]

def make_blog(slug,title,topic,fields,owner,all_slugs):
 sections=[{'heading':h,'paragraphs':blog_paragraphs(title,topic,fields,owner,i)} for i,h in enumerate(BLOG_HEADS)]
 return {'title':title,'description':f'A controlled account-management workflow for {topic}, with source evidence, authority boundaries, adverse cases, and verified closure.','published':DATE,'updated':DATE,'readMinutes':15,'heroImage':f'/october-13-2026/{slug}.svg','intro':[f'{title} turns {topic} into a bounded, reviewable account workflow. It preserves what the client said, what the systems show, which owner decided, what was executed, and how the destination was verified.',f'This operating guide is designed for outsourced account support. It does not transfer commercial, legal, privacy, security, financial, contractual, or relationship authority, and it does not promise a client outcome.'],'takeaways':[f'Capture {fields} before the case advances.','Keep source facts, interpretations, owner decisions, actions, and client messages in separate fields.',f'Route consequential judgment to the {owner}.','Close only when approval, execution, client communication, and destination evidence agree.'],'sections':sections,'banners':[{'label':'Evidence checkpoint','title':'Keep the source attached','body':'Preserve identity, version, time, and scope before routing the item.','href':'/services/account-reporting','link':'Review account reporting support'},{'label':'Authority checkpoint','title':'Keep consequential decisions named','body':f'The {owner} remains accountable for approval and risk acceptance.','href':'/services/escalation-coordination','link':'Review escalation support'},{'label':'Closure checkpoint','title':'Verify the destination state','body':'Reconcile the approved action, client message, system result, and residual list.','href':'/services/client-request-routing','link':'Review request routing support'}],'table':{'caption':f'{title} control checks','headers':['Checkpoint','Evidence','Stop signal'],'rows':[['Identity',fields,'Client, record, or period mismatch'],['Authority',f'Named {owner} and effective approval','Approval is absent or expired'],['Execution','Destination event and receipt','Proposed work is presented as complete'],['Closure','Reconciliation and residual review','Systems or client message disagree']]},'chart':[{'label':'Source check','value':88,'color':'#0f766e'},{'label':'Owner gate','value':72,'color':'#6366f1'},{'label':'Verification','value':94,'color':'#d97706'}],'chartMeta':{'title':f'{title} illustrative control coverage','desc':'Three bars illustrate source, owner, and verification checks without presenting measured performance.','heading':'Illustrative control coverage','method':'Illustrative workflow-design values only; they are not client results, benchmarks, or performance claims.'},'graphic':{'title':f'{title} evidence path','desc':'A three-step evidence path from source capture through owner decision to verified closure.','heading':'Bounded account workflow','steps':[{'title':'1  Capture','line1':'Source, identity,','line2':'scope, and time','color':'#b9dfce'},{'title':'2  Decide','line1':'Owner, authority,','line2':'limits, and receipt','color':'#d8d7ff'},{'title':'3  Verify','line1':'Client message,','line2':'system, residuals','color':'#f6d7a8'}],'caption':'Preparation, accountable decision, and verified destination remain separate.'},'quote':{'text':'Accountability is the property that ensures actions can be traced uniquely to the entity responsible.','source':'NIST Accountability Glossary','url':'https://csrc.nist.gov/glossary/term/accountability'},'script':[f'We are reviewing {topic} against the retained source record and current owner authority.',f'The next verified update will identify what is confirmed, what remains open, and which owner controls the decision.',f'We will close the item only after the approved action and client-facing record agree.'],'faqs':[{'q':f'Can an outsourced specialist complete {topic} alone?','a':f'The specialist can prepare and coordinate the workflow, but the {owner} retains consequential decisions and approvals.'},{'q':'What stops the workflow?','a':'A client mismatch, missing source, conflicting authority, unsafe destination, or absent verification stops dependent work.'},{'q':'What proves closure?','a':'The approval, execution event, client communication, destination state, and residual register must reconcile.'}],'sources':SOURCES[:3],'related':[x for x in all_slugs if x!=slug][:3]}

def research_paragraphs(title,question,unit,index):
 stage=RESEARCH_HEADS[index]
 lead='Limitations.' if stage.startswith('Limitations') else f'{stage}.'
 return [
  f'{lead} {title} tests {question}. Stage {index+1} declares {unit} as the observation unit and freezes the population, system boundary, local and UTC times, source versions, inclusion rules, exclusions, and intended decision before outcomes are reviewed. Record OAM-R-1013-{index+1:02d} distinguishes source events, client statements, business interpretations, owner decisions, implementation evidence, and unresolved hypotheses. This prospective design reports no completed client outcome and establishes no universal benchmark.',
  f'At the {stage.lower()} stage for {title}, include routine, missing-source, wrong-identity, conflicting-version, late-arriving, inaccessible-system, unavailable-owner, reversed, corrected, and reopened cases. Two reviewers classify a stratified subset independently with written anchors, preserve first-pass disagreement, and adjudicate against retained evidence. Report numerator, denominator, exclusions, null values, age bands, correction rate, disagreement, and residual cases together. Do not silently impute a favorable state or remove difficult accounts after seeing the result.',
  f'Alternative explanations evaluated during {stage.lower()} for {title} include case mix, account complexity, configuration, logging gaps, clock drift, synchronization, ownership changes, policy versions, seasonality, client responsiveness, and selection effects. The ten public sources guide governance and control design but do not inspect this environment, prove causation, certify a provider, or authorize action. Preserve the protocol, query, codebook, sample receipt, chronology, reviewer notes, decision log, approved correction, verification, limitations, and refresh trigger so an authorized analyst can reproduce the bounded result without retaining unnecessary client data.'
 ]

research_slugs=[x[0] for x in RESEARCH]
